65	            {
66	              defaultMessage: 'This section contains content from the catalog. {docLink} on how to replace it.',
67	              id: 'home.description.shop_products',
68	              description:
69	                '{docLink} is a html button that links the user to https://sfdc.co/business-manager-manage-catalogs',
