82	                    bottom: '-2px',
83	                    margin: '0 auto',
84	                    left: 0,
85	                    right: 0,
86	                    background: 'gray.700',
87	                  }}
88	                  _hover={{ textDecoration: 'none' }}
89	                >
90	                  {intl.formatMessage({
91	                    defaultMessage: 'Read docs',
92	                    id: 'home.link.read_docs',
93	                  })}
94	                </Link>
95	              ),
96	            },
97	          )}
98	        >
