108	// --- Normal (published) home ---
109	
110	const HomeNormal = () => {
111	  const einstein = useEinstein();
112	  const { pathname } = useLocation();
113	
114	  const { res } = useServerContext();
115	  if (res) {
116	    res.set(
117	      'Cache-Control',
118	      `s-maxage=${MAX_CACHE_AGE as number}, stale-while-revalidate=${STALE_WHILE_REVALIDATE as number}`,
119	    );
120	  }
121	
122	  const { data: contentfulData, isLoading: contentfulLoading } = useContentfulEntries<HomepageEntry>('homepage');
123	  const homepageContent = useContentfulLiveUpdates(contentfulData?.[0] ?? null);
124	
125	  useEffect(() => {
126	    einstein.sendViewPage(pathname);
127	  }, []);
128	
129	  if (contentfulLoading) {
130	    return (
131	      <Box display="flex" justifyContent="center" py={16}>
132	        <Spinner size="xl" />
133	      </Box>
134	    );
135	  }
136	
137	  if (!homepageContent) return null;
138	
139	  return <HomepageContent />;
140	};
141	
142	// --- Preview (draft) home ---
143	
144	type HomePreviewContentProps = {
145	  entryId: string;
146	};
147	
148	const HomePreviewContent = ({ entryId }: HomePreviewContentProps) => {
149	  const { data, isLoading, error } = useContentfulEntry<AnyContentfulEntry>(entryId, true);
150	  const liveData = useContentfulLiveUpdates(data);
151	
152	  if (isLoading) {
153	    return (
154	      <Box display="flex" justifyContent="center" py={16}>
155	        <Spinner size="xl" />
156	      </Box>
157	    );
158	  }
159	
160	  if (error) {
161	    return (
162	      <Box p={8}>
163	        <Text color="red.500">Error loading preview: {error.message}</Text>
164	      </Box>
165	    );
166	  }
167	
168	  if (!liveData) return null;
169	
170	  const contentTypeId = liveData.sys?.contentType?.sys?.id;
171	
172	  if (contentTypeId !== 'homepage') {
173	    return (
174	      <Box p={8}>
175	        <Text>Preview for content type &ldquo;{contentTypeId}&rdquo; is not yet configured.</Text>
176	      </Box>
177	    );
178	  }
179	
180	  return <HomepageContent />;
181	};
