                {subtitle && (
                    <Text color={'gray.700'} fontWeight={600}>
                        {subtitle}
                    </Text>
                )}
                {actions && (
                    <Box paddingTop="2" width={{base: 'full', md: 'auto'}}>
                        {actions}
                    </Box>
                )}
            </Stack>
            {children}
        </Box>
    )
}

Section.displayName = 'Section'

