                  src={hoverImage.src}
                  alt={hoverImage.alt}
                  data-role="hover-overlay"
                  __css={styles.hoverSwapOverlay}
                  {...imageLoadingProps(false)}
                />
              </chakra.div>
            );
          }

          return (
            <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
              <chakra.img
                src={image.src}
                alt={image.alt}
                __css={styles.image}
                {...imageLoadingProps(isPrimaryPosition)}
              />
            </chakra.div>
          );
        })}
      </chakra.div>

      {hasBadge && (
        <chakra.div __css={styles.badge} data-card-slot="badge">
